"""Scientific comparison figure and offline viewer of actual saved native A11 states."""
import json,sys
from pathlib import Path
import numpy as np
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'wtc1_simulation_v8/output/aircraft_a11'

def main(caseid):
    import reportlab
    from reportlab.graphics.shapes import Drawing,String,Line,PolyLine
    from reportlab.graphics.charts.lineplots import LinePlot
    from reportlab.graphics import renderSVG
    from reportlab.lib import colors
    d=OUT/'r0'/caseid;m=json.loads((d/'mesh.json').read_text());r=json.loads((d/'review.json').read_text());z=np.load(d/'verified_states_SI.npz');L=np.load(d/'balance_history_SI.npz');dst=OUT/'visualisation';dst.mkdir(exist_ok=True)
    fig=Drawing(1100,780);fig.add(String(35,750,'AIRCRAFT-A11 — premier contact du nez, états natifs',fontSize=21));fig.add(String(35,723,'Diagnostic numérique ; rupture et écrasement historiques non qualifiés',fontSize=13));datasets=[[],[],[]];labels=[]
    for p in sorted((OUT/'r0').glob('NOSE*/review.json')):
        rr=json.loads(p.read_text());l=np.load(p.parent/'balance_history_SI.npz');label=rr['case']['id'];t=l['time_s']*1000
        labels.append(label)
        for dstdata,values in zip(datasets,[l['contact_impulse_Ns'][:,0],l['generated_energy_J']/1000,l['energy_residual_J']/1000]):dstdata.append(list(zip(t.tolist(),values.tolist())))
    palette=[colors.HexColor(q) for q in ['#126a9f','#ad4727','#318454','#9d56a7']]
    for n,(data,(px,py),title) in enumerate(zip(datasets,[(80,410),(625,410),(80,80)],['Impulsion X sur façade (N·s)','Énergie générée, RKE compté une fois (kJ)','Résidu du bilan global (kJ)'])):
        chart=LinePlot();chart.x=px;chart.y=py;chart.width=400;chart.height=240;chart.data=data;chart.joinedLines=1;chart.xValueAxis.valueMin=0
        for i in range(len(data)):chart.lines[i].strokeColor=palette[i%len(palette)];chart.lines[i].strokeWidth=1
        fig.add(chart);fig.add(String(px,py+265,title,fontSize=13));fig.add(String(px+120,py-38,'Temps calculé (ms)',fontSize=11))
    for i,label in enumerate(labels):fig.add(String(80+i*240,685,label,fontSize=11,fillColor=palette[i%len(palette)]))
    x=z['initial_positions_m'];u=z['displacement_m'][-1];nose=[q for q,pid in zip(m['original_triangle_node_ids'],m['aircraft_triangle_part_ids']) if pid==21]
    for tr in nose:
        idx=np.array(tr+[tr[0]])-1
        for pos,col in [(x,colors.lightgrey),(x+u,colors.HexColor('#126a9f'))]:
            v=pos[idx];v=np.column_stack([625+(np.clip(v[:,0],-.35,.6)+.35)*400/.95,80+(np.clip(v[:,2],-1,1)+1)*120]);fig.add(PolyLine(v.ravel().tolist(),strokeColor=col,strokeWidth=.35))
    fig.add(Line(625+.30*400/.95,80,625+.30*400/.95,320,strokeColor=colors.HexColor('#ad4727')));fig.add(String(625,345,'Nez initial gris / final bleu ; façade orange (X=-0,05 m)',fontSize=12));fig.add(String(650,40,'X : -0,35 à +0,60 m ; Z : -1 à +1 m ; déplacement ×1',fontSize=11));renderSVG.drawToFile(fig,str(dst/'bilans_et_nez.svg'))
    triangles=m['original_triangle_node_ids'];pids=m['aircraft_triangle_part_ids'];fac=m['facade_quads_node_ids'];beam=m['original_beam_node_ids'];used=sorted({n for row in triangles+fac+beam for n in row});idx=np.array(used)-1;lookup={n:i for i,n in enumerate(used)}
    payload={'case':caseid,'time_ms':(z['time_s']*1000).tolist(),'x_m':np.round(x[idx],6).tolist(),'u_m':np.round(z['displacement_m'][:,idx],7).tolist(),'faces':[[p]+[lookup[n] for n in tr] for p,tr in zip(pids,triangles)]+[[31]+[lookup[n] for n in tr] for tr in fac],'beams':[[lookup[n] for n in tr] for tr in beam],'material_pass':r['material_domain_pass'],'numerical_pass':r['numerical_gates_pass'],'failed':r['failed_checks'],'end_ms':r['actual_main_end_time_ms'],'onset_ms':r['contact_onset_by_segment_ms']}
    html='''<!doctype html><html lang="fr"><meta charset="utf-8"><title>WTC1 A11 — premier contact</title><style>body{margin:0;background:#101824;color:#e8edf4;font:16px system-ui}main{max-width:1300px;margin:auto;padding:24px}h1{font-size:25px;margin:0 0 10px}p{max-width:1050px;line-height:1.5}canvas{width:100%;height:620px;background:#182433;border-radius:12px}.controls{display:flex;align-items:center;gap:14px;flex-wrap:wrap;padding:14px 0}button,select{padding:9px;background:#314256;color:white;border:1px solid #58718b;border-radius:6px}input{width:280px}small{color:#bccbdb}#status{padding:12px;background:#253446;border-radius:8px}a{color:#91cef4}</style><main><h1>Boeing / façade — premier contact du nez</h1><p>Vue des déplacements sauvegardés par le solveur OpenRadioss. Échelle de déformation réelle (×1). La lecture est ralentie ; le temps physique reste affiché en millisecondes. Il ne s'agit pas encore d'une traversée historique calculée.</p><div id="status"></div><div class="controls"><button id="play">Lecture ralentie</button><input id="time" type="range" min="0" step="1" value="0"><b id="label"></b><select id="scope"><option value="full">Avion entier</option><option value="nose">Nez, vue rapprochée</option></select><label>Rotation <input id="yaw" type="range" min="-90" max="90" value="-25"></label></div><canvas id="view"></canvas><p><small>Bleu : avion ; vert : radôme ; orange : façade. Les lignes internes représentent la structure du modèle. Masses, matériaux et assemblages sont hérités ; aucune rupture/érosion, délamination ou loi d'écrasement du cœur n'est transférée. Les ailes et moteurs sont inclus dans le contact mais n'atteignent pas encore la façade dans cette fenêtre. Les critères échoués restent dans le rapport.</small></p><p><a href="bilans_et_nez.png">Figure des bilans et du nez</a></p></main><script>const D=PAYLOAD;const cv=document.querySelector('#view'),ctx=cv.getContext('2d'),sl=document.querySelector('#time'),lab=document.querySelector('#label'),scope=document.querySelector('#scope'),yaw=document.querySelector('#yaw');sl.max=D.time_ms.length-1;document.querySelector('#status').textContent=D.case+' — durée '+D.end_ms.toFixed(6)+' ms ; contrôles numériques : '+(D.numerical_pass?'réussis':'échoués')+' ; domaine matériau : '+(D.material_pass?'critères réussis':'dépassé')+'. Échecs : '+(D.failed.join(', ')||'aucun')+'.';let playing=false,last=0;function render(){let b=cv.getBoundingClientRect();cv.width=b.width*devicePixelRatio;cv.height=b.height*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);ctx.clearRect(0,0,b.width,b.height);let k=+sl.value;lab.textContent=D.time_ms[k].toFixed(6)+' ms';let close=scope.value==='nose',a=(+yaw.value)*Math.PI/180,co=Math.cos(a),si=Math.sin(a),centre=close?[.2,0,0]:[22,0,1],scale=Math.min(b.width,b.height)/(close?4:62),points=D.x_m.map((q,i)=>{let p=q.map((v,j)=>v+D.u_m[k][i][j]-centre[j]);return[b.width/2+scale*(co*p[0]+si*p[1]),b.height/2-scale*(.89*p[2]-.32*(-si*p[0]+co*p[1]))]});ctx.lineWidth=.55;for(const f of D.faces){if(close&&f.slice(1).every(n=>D.x_m[n][0]>3))continue;let color=f[0]===31?'#ea9556':f[0]===21?'#5adcaf':'#89bfe6';ctx.strokeStyle=color;ctx.globalAlpha=f[0]===31?.30:.5;ctx.beginPath();f.slice(1).forEach((n,i)=>{let p=points[n];i?ctx.lineTo(...p):ctx.moveTo(...p)});ctx.closePath();ctx.stroke()}ctx.globalAlpha=.15;ctx.strokeStyle='#b9d9f4';for(let e of D.beams){if(close&&e.every(n=>D.x_m[n][0]>3))continue;ctx.beginPath();ctx.moveTo(...points[e[0]]);ctx.lineTo(...points[e[1]]);ctx.stroke()}ctx.globalAlpha=1;ctx.fillStyle='#e8edf4';ctx.font='14px system-ui';ctx.fillText(close?'Vue rapprochée du nez · déplacements ×1':'Avion entier · déplacements ×1',20,28)}sl.oninput=render;scope.onchange=render;yaw.oninput=render;window.onresize=render;document.querySelector('#play').onclick=()=>{playing=!playing;document.querySelector('#play').textContent=playing?'Pause':'Lecture ralentie'};function tick(t){if(playing&&t-last>300){sl.value=(+sl.value+1)%D.time_ms.length;last=t;render()}requestAnimationFrame(tick)}render();requestAnimationFrame(tick);</script></html>'''
    (dst/'premier_contact.html').write_text(html.replace('bilans_et_nez.png','bilans_et_nez.svg').replace('PAYLOAD',json.dumps(payload,separators=(',',':'))),encoding='utf-8')
    (dst/'provenance.json').write_text(json.dumps({'case':caseid,'inputs':[str(d/'verified_states_SI.npz'),str(d/'mesh.json'),str(d/'review.json')],'native_solver_state_viewer':True,'deformation_scale':1,'physical_time_unit':'ms','playback_time_is_artificial':True,'reportlab_version':reportlab.Version,'source_binary_inertias_not_visualization_derived':True},indent=2),encoding='utf-8');print({'viewer':str(dst/'premier_contact.html'),'figure':str(dst/'bilans_et_nez.svg')})

if __name__=='__main__':main(sys.argv[1])
